'use client';

// On/off switches in Settings and onboarding (Reduce motion, AI suggestions).
// Generated by the shadcn/ui CLI on Radix Switch and adapted: a 52×32 track
// whose knob springs across (v2 spec 4.4), a visible border when off so the
// state doesn't depend on a faint gray, and SwitchRow puts the label and the
// switch in one 48px row.
import * as React from 'react';
import { cn } from '@/lib/utils';
import { Switch as SwitchPrimitive } from 'radix-ui';
import { useFeedback } from '@/lib/sound/useFeedback';

function Switch({ className, onCheckedChange, ...props }: React.ComponentProps<typeof SwitchPrimitive.Root>) {
  const feedback = useFeedback();
  return (
    <SwitchPrimitive.Root
      onCheckedChange={(checked) => {
        feedback('toggle');
        onCheckedChange?.(checked);
      }}
      data-slot="switch"
      className={cn(
        'peer inline-flex h-8 w-[52px] shrink-0 items-center rounded-full border-2 border-ink-soft bg-surface-2 transition-colors duration-(--dur-fast) data-checked:border-primary data-checked:bg-primary data-disabled:cursor-not-allowed data-disabled:opacity-50',
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className="pointer-events-none block size-6 translate-x-0.5 rounded-full bg-ink-soft transition-transform duration-(--dur-spring-snappy) ease-(--spring-snappy) data-checked:translate-x-[22px] data-checked:bg-on-primary"
      />
    </SwitchPrimitive.Root>
  );
}

function SwitchRow({
  id,
  label,
  description,
  checked,
  onCheckedChange,
}: {
  id: string;
  label: string;
  description?: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}) {
  // When the row gets narrow for its text (a phone at 130% and up), the
  // switch moves under its label instead of squeezing it (v2.1 F-02). The
  // em-based container query follows the text size, not only the screen.
  return (
    <div className="@container">
      <div data-setting-row className="flex min-h-12 items-center justify-between gap-x-4 gap-y-2 @max-[18em]:flex-col @max-[18em]:items-start">
        <label htmlFor={id} className="flex min-w-0 flex-col">
          <span>{label}</span>
          {description && <span className="text-caption text-ink-soft">{description}</span>}
        </label>
        <Switch id={id} checked={checked} onCheckedChange={onCheckedChange} className="shrink-0" />
      </div>
    </div>
  );
}

export { Switch, SwitchRow };
